"""Probabilistic CKY with backpointers, and PARSEVAL precision/recall/F1."""
from collections import defaultdict

def pcky(words, lex, binary):
    n = len(words); best = defaultdict(dict); back = {}
    for i, w in enumerate(words):
        for A, p in lex.get(w, {}).items():
            best[(i, i + 1)][A] = p; back[(i, i + 1, A)] = w
    for span in range(2, n + 1):
        for i in range(0, n - span + 1):
            j = i + span
            for k in range(i + 1, j):
                for (A, B, C), p in binary.items():
                    if B in best[(i, k)] and C in best[(k, j)]:
                        cand = p * best[(i, k)][B] * best[(k, j)][C]
                        if cand > best[(i, j)].get(A, 0):
                            best[(i, j)][A] = cand; back[(i, j, A)] = (k, B, C)
    return best, back

def tree(back, i, j, A):
    b = back[(i, j, A)]
    if isinstance(b, str): return f"({A} {b})"
    k, B, C = b
    return f"({A} {tree(back, i, k, B)} {tree(back, k, j, C)})"

def spans(back, i, j, A, out):
    b = back[(i, j, A)]
    if isinstance(b, str): return out
    out.add((A, i, j)); k, B, C = b
    spans(back, i, k, B, out); spans(back, k, j, C, out); return out

# 1. Astronomers saw stars with ears (grammar already in CNF)
lex = {"astronomers": {"NP": 0.1}, "saw": {"V": 1.0, "NP": 0.04}, "stars": {"NP": 0.18},
       "with": {"P": 1.0}, "ears": {"NP": 0.18}}
binary = {("S", "NP", "VP"): 1.0, ("NP", "NP", "PP"): 0.4, ("PP", "P", "NP"): 1.0,
          ("VP", "V", "NP"): 0.7, ("VP", "VP", "PP"): 0.3}
w = "astronomers saw stars with ears".split()
best, back = pcky(w, lex, binary)
print(f"P(best S) = {best[(0, len(w))]['S']:.7f}")
print(tree(back, 0, len(w), "S"))
print("cell [2,5] (stars with ears):", {k: round(v, 6) for k, v in best[(2, 5)].items()})

# 2. The flight includes a meal (illustrative probabilities)
lex2 = {"the": {"Det": 0.4}, "a": {"Det": 0.4}, "flight": {"N": 0.02}, "meal": {"N": 0.01}, "includes": {"V": 0.05}}
bin2 = {("NP", "Det", "N"): 0.3, ("VP", "V", "NP"): 0.2, ("S", "NP", "VP"): 0.8}
w2 = "the flight includes a meal".split()
b2, bk2 = pcky(w2, lex2, bin2)
print(f"NP over 'the flight' = 0.3 x 0.4 x 0.02 = {b2[(0, 2)]['NP']:.4f}")
print(f"P(S) = {b2[(0, 5)]['S']:.3e};", tree(bk2, 0, 5, "S"))

# 3. PARSEVAL: compare predicted constituents with gold (VP-attachment taken as gold here)
gold = {("S", 0, 5), ("VP", 1, 5), ("VP", 1, 3), ("PP", 3, 5)}
pred = spans(back, 0, len(w), "S", set())
correct = gold & pred
P, Rc = len(correct) / len(pred), len(correct) / len(gold)
print("predicted:", sorted(pred, key=lambda s: (s[1], -s[2])))
print(f"labeled precision {P:.2f}, recall {Rc:.2f}, F1 {2*P*Rc/(P+Rc):.2f}")
P, Rc = 6 / 100, 6 / 6
print(f"guessing 100 brackets that include all 6 gold: precision {P:.2f}, recall {Rc:.2f}, F1 {2*P*Rc/(P+Rc):.3f}")
